#!/usr/bin/env node
// Renders the public API reference from the committed OpenAPI 3.1 spec (issue #816).
//
// The spec (`docs/api/openapi.json`, owned by apps/api and regenerated by `pnpm openapi:generate`) is
// the only input. This script writes `docs/api/reference.md`, a Markdown page that the docs site
// (`scripts/docs-site.mjs`, DOCS-001) renders and link-checks like every other page. It never reads
// the network and uses only the repository's Prettier, so the output is a pure function of the spec.
//
// Every operation, parameter, request body, response, component schema and example in the spec appears
// in the reference. Paths under `/internal` are never rendered: the Run Broker API is not public. A spec
// that does not parse, or that has a shape the reference cannot describe, fails loudly.
//
// Usage:
//   node scripts/render-api-reference.mjs            write docs/api/reference.md
//   node scripts/render-api-reference.mjs --check    exit 1 when the committed page is stale
//   node scripts/render-api-reference.mjs --root <d> operate on another repository root (tests)
// Exits 1 on a stale page or an invalid spec, and 2 on a usage error.

import { readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import * as prettier from 'prettier';

import { slugify } from './check-claude-md.mjs';

export const SPEC_FILE = 'docs/api/openapi.json';
export const REFERENCE_FILE = 'docs/api/reference.md';
const HTTP_METHODS = ['get', 'put', 'post', 'delete', 'options', 'head', 'patch', 'trace'];
const INTERNAL_PATH = /^\/internal(\/|$)/;

/** @typedef {Record<string, unknown>} JsonObject */
/** @typedef {{ method: string, route: string, operation: JsonObject }} Operation */

/**
 * @param {unknown} value
 * @returns {value is JsonObject}
 */
function isObject(value) {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/**
 * @param {unknown} value
 * @returns {JsonObject} the value when it is an object, otherwise an empty object
 */
function asObject(value) {
  return isObject(value) ? value : {};
}

/**
 * @param {unknown} value
 * @returns {unknown[]} the value when it is an array, otherwise an empty array
 */
function asArray(value) {
  return Array.isArray(value) ? value : [];
}

/**
 * @param {unknown} value
 * @returns {string} the value when it is a string, otherwise an empty string
 */
function asText(value) {
  return typeof value === 'string' ? value : '';
}

/**
 * Parses and validates the spec text. Fails closed: anything the reference cannot describe throws.
 * @param {string} text the spec file contents
 * @returns {JsonObject} the parsed document
 */
export function parseSpec(text) {
  /** @type {unknown} */
  let parsed;
  try {
    parsed = JSON.parse(text);
  } catch (error) {
    throw new Error(
      `${SPEC_FILE} is not valid JSON: ${error instanceof Error ? error.message : String(error)}`,
    );
  }
  if (!isObject(parsed)) throw new Error(`${SPEC_FILE}: the document must be an object`);
  if (typeof parsed.openapi !== 'string' || !parsed.openapi.startsWith('3.1.')) {
    throw new Error(`${SPEC_FILE}: openapi must be a 3.1.x version`);
  }
  const info = asObject(parsed.info);
  if (typeof info.title !== 'string') throw new Error(`${SPEC_FILE}: info.title is required`);
  if (!isObject(parsed.paths)) throw new Error(`${SPEC_FILE}: paths must be an object`);
  /** @type {Set<string>} */
  const seen = new Set();
  for (const [route, item] of Object.entries(parsed.paths)) {
    if (!route.startsWith('/')) throw new Error(`${SPEC_FILE}: path ${route} must start with /`);
    if (!isObject(item)) throw new Error(`${SPEC_FILE}: path ${route} must be an object`);
    if (INTERNAL_PATH.test(route)) continue;
    for (const method of HTTP_METHODS) {
      const operation = item[method];
      if (operation === undefined) continue;
      const id = asObject(operation).operationId;
      if (typeof id !== 'string') {
        throw new TypeError(`${SPEC_FILE}: ${method.toUpperCase()} ${route} needs an operationId`);
      }
      if (seen.has(id)) throw new Error(`${SPEC_FILE}: operationId ${id} is not unique`);
      seen.add(id);
      const responses = asObject(asObject(operation).responses);
      if (Object.keys(responses).length === 0) {
        throw new Error(`${SPEC_FILE}: ${id} has no responses`);
      }
    }
  }
  return parsed;
}

/**
 * Every public operation, in spec order.
 * @param {JsonObject} spec
 * @returns {Operation[]}
 */
export function listOperations(spec) {
  /** @type {Operation[]} */
  const operations = [];
  for (const [route, rawItem] of Object.entries(asObject(spec.paths))) {
    if (INTERNAL_PATH.test(route)) continue;
    const item = asObject(rawItem);
    for (const method of HTTP_METHODS) {
      if (item[method] !== undefined) {
        operations.push({ method, route, operation: asObject(item[method]) });
      }
    }
  }
  return operations;
}

/**
 * Escapes text for a Markdown table cell.
 * @param {unknown} value
 * @returns {string}
 */
function cell(value) {
  return asText(value).replace(/\r?\n/g, ' ').replace(/\|/g, '\\|');
}

/**
 * A fenced JSON block whose fence is longer than any backtick run in the content.
 * @param {unknown} value
 * @returns {string}
 */
function jsonBlock(value) {
  const body = JSON.stringify(value, null, 2);
  const longest = Math.max(2, ...[...body.matchAll(/`+/g)].map((match) => match[0].length));
  const fence = '`'.repeat(longest + 1);
  return `${fence}json\n${body}\n${fence}\n`;
}

/**
 * @param {string} ref a `#/components/<kind>/<name>` reference
 * @returns {string} the component name
 */
function refName(ref) {
  return ref.slice(ref.lastIndexOf('/') + 1);
}

/**
 * Resolves a `$ref` to a parameter, header or response component; anything else is returned as is.
 * @param {JsonObject} spec
 * @param {unknown} value
 * @returns {JsonObject}
 */
function resolve(spec, value) {
  const raw = asObject(value);
  if (typeof raw.$ref !== 'string') return raw;
  const match = /^#\/components\/(parameters|headers|responses)\/(.+)$/.exec(raw.$ref);
  if (match === null) throw new Error(`${SPEC_FILE}: unsupported $ref ${raw.$ref}`);
  const group = asObject(asObject(spec.components)[match[1] ?? '']);
  const target = asObject(group[match[2] ?? '']);
  if (Object.keys(target).length === 0)
    throw new Error(`${SPEC_FILE}: ${raw.$ref} does not resolve`);
  return target;
}

/**
 * Short, human-readable type of a schema. Component references link to their schema section.
 * @param {unknown} value
 * @returns {string}
 */
function typeOf(value) {
  const schema = asObject(value);
  if (typeof schema.$ref === 'string') {
    const name = refName(schema.$ref);
    return `[${name}](#${slugify(name)})`;
  }
  for (const key of ['anyOf', 'oneOf']) {
    const variants = asArray(schema[key]);
    if (variants.length > 0) return variants.map((variant) => typeOf(variant)).join(' or ');
  }
  const values = asArray(schema.enum);
  if (values.length > 0) {
    return `enum: ${values.map((item) => `\`${JSON.stringify(item)}\``).join(', ')}`;
  }
  if (schema.type === 'array') return `array of ${typeOf(schema.items)}`;
  if (schema.type === 'string' && typeof schema.format === 'string') {
    return `string (${schema.format})`;
  }
  if (typeof schema.type === 'string') return schema.type;
  return 'any';
}

/**
 * Public Markdown for the security requirements: `a + b` (both) or `a or b` (either).
 * @param {JsonObject} spec
 * @param {JsonObject} operation
 * @returns {string}
 */
function authentication(spec, operation) {
  const requirements = asArray(operation.security ?? spec.security);
  if (requirements.length === 0) return 'None (public).';
  return requirements
    .map((requirement) => {
      const names = Object.keys(asObject(requirement));
      return names.length === 0 ? 'None.' : `\`${names.join('` + `')}\``;
    })
    .join(' or ');
}

/**
 * @param {JsonObject} spec
 * @param {JsonObject} operation
 * @returns {string[]} the parameter table rows
 */
function parameterRows(spec, operation) {
  return asArray(operation.parameters).map((raw) => {
    const parameter = resolve(spec, raw);
    const required = parameter.required === true ? 'yes' : 'no';
    const type = typeOf(parameter.schema);
    return `| \`${cell(parameter.name)}\` | ${cell(parameter.in)} | ${required} | ${type} | ${cell(parameter.description)} |`;
  });
}

/**
 * Words for an example key: `nothingRunning` becomes `nothing running`.
 * @param {string} name
 * @returns {string}
 */
function exampleTitle(name) {
  return name.replace(/([a-z0-9])([A-Z])/g, '$1 $2').toLowerCase();
}

/**
 * Example payloads of a media-type object: `examples` (named) first, then a single `example`.
 * @param {JsonObject} media
 * @returns {Array<{ title: string, value: unknown }>}
 */
function examplesOf(media) {
  /** @type {Array<{ title: string, value: unknown }>} */
  const out = [];
  for (const [name, raw] of Object.entries(asObject(media.examples))) {
    const example = asObject(raw);
    if ('value' in example) {
      out.push({
        title: typeof example.summary === 'string' ? example.summary : exampleTitle(name),
        value: example.value,
      });
    }
  }
  if (out.length === 0 && 'example' in media) out.push({ title: 'Example', value: media.example });
  return out;
}

/**
 * @param {JsonObject} content a `content` map of media types
 * @returns {string[]} the Markdown for each media type and its examples
 */
function mediaLines(content) {
  const lines = [];
  for (const [mediaType, raw] of Object.entries(content)) {
    const media = asObject(raw);
    lines.push(`Content type \`${mediaType}\`: ${typeOf(media.schema)}.`, '');
    for (const example of examplesOf(media)) {
      lines.push(`Example: ${example.title}.`, '', jsonBlock(example.value));
    }
  }
  return lines;
}

/**
 * @param {JsonObject} spec
 * @param {JsonObject} operation
 * @returns {string[]} the Markdown lines for the request body, or none
 */
function requestBodySection(spec, operation) {
  if (operation.requestBody === undefined) return [];
  const body = resolve(spec, operation.requestBody);
  const required = body.required === true ? 'required' : 'optional';
  return [`**Request body** (${required})`, '', ...mediaLines(asObject(body.content))];
}

/**
 * @param {JsonObject} spec
 * @param {JsonObject} operation
 * @returns {string[]} the Markdown lines for every response
 */
function responseSections(spec, operation) {
  const lines = [];
  for (const [status, raw] of Object.entries(asObject(operation.responses))) {
    const response = resolve(spec, raw);
    lines.push(`#### Response ${status}`, '', asText(response.description), '');
    const headers = Object.entries(asObject(response.headers));
    if (headers.length > 0) {
      lines.push('| Header | Description |', '| --- | --- |');
      for (const [name, header] of headers) {
        lines.push(`| \`${cell(name)}\` | ${cell(resolve(spec, header).description)} |`);
      }
      lines.push('');
    }
    lines.push(...mediaLines(asObject(response.content)));
  }
  return lines;
}

/**
 * @param {JsonObject} spec
 * @param {Operation} entry
 * @returns {string[]} the Markdown for one operation, starting at its `###` heading
 */
function operationSection(spec, { method, route, operation }) {
  const lines = [`### ${method.toUpperCase()} ${route}`, ''];
  if (operation.deprecated === true) {
    lines.push(
      '> **Deprecated.** This operation is kept for existing clients and may be removed. Read the description for its replacement.',
      '',
    );
  }
  if (typeof operation.summary === 'string') lines.push(`**${operation.summary}**`, '');
  if (typeof operation.description === 'string') lines.push(operation.description, '');
  lines.push(`- Operation ID: \`${asText(operation.operationId)}\``);
  lines.push(`- Authentication: ${authentication(spec, operation)}`, '');
  const rows = parameterRows(spec, operation);
  if (rows.length > 0) {
    lines.push(
      '| Parameter | In | Required | Type | Description |',
      '| --- | --- | --- | --- | --- |',
      ...rows,
      '',
    );
  }
  lines.push(...requestBodySection(spec, operation));
  lines.push(...responseSections(spec, operation));
  return lines;
}

/**
 * @param {string} name the component schema name
 * @param {JsonObject} schema
 * @returns {string[]} the Markdown for one component schema
 */
function schemaSection(name, schema) {
  const lines = [`### ${name}`, ''];
  if (typeof schema.description === 'string') lines.push(schema.description, '');
  const properties = Object.entries(asObject(schema.properties));
  const required = new Set(asArray(schema.required).map((item) => asText(item)));
  if (properties.length > 0) {
    lines.push('| Property | Type | Required | Description |', '| --- | --- | --- | --- |');
    for (const [property, definition] of properties) {
      const isRequired = required.has(property) ? 'yes' : 'no';
      const description = asText(asObject(definition).description);
      lines.push(
        `| \`${cell(property)}\` | ${typeOf(definition)} | ${isRequired} | ${cell(description)} |`,
      );
    }
    lines.push('');
  }
  lines.push('Full schema:', '', jsonBlock(schema));
  return lines;
}

/**
 * @typedef {{ title: string, description?: string, entries: Operation[] }} Group
 */

/**
 * Operations grouped by their first tag, in tag order. Operations with no declared tag (or an undeclared
 * one) are kept under "Other operations" so none is silently dropped.
 * @param {unknown[]} tags
 * @param {Operation[]} operations
 * @returns {Group[]}
 */
function groupOperations(tags, operations) {
  /**
   * @param {Operation} entry
   * @returns {unknown}
   */
  const firstTag = (entry) => asArray(entry.operation.tags)[0];
  const declared = tags.map((tag) => asObject(tag));
  /** @type {Group[]} */
  const groups = declared.map((tag) => {
    const description = asText(tag.description);
    return {
      title: asText(tag.name),
      ...(description === '' ? {} : { description }),
      entries: operations.filter((entry) => firstTag(entry) === tag.name),
    };
  });
  const names = new Set(declared.map((tag) => tag.name));
  const others = operations.filter((entry) => !names.has(firstTag(entry)));
  if (others.length > 0) groups.push({ title: 'Other operations', entries: others });
  return groups.filter((group) => group.entries.length > 0);
}

/**
 * Renders the reference page. Pure: the same spec always yields the same Markdown.
 * @param {JsonObject} spec a parsed, validated spec (see parseSpec)
 * @returns {string}
 */
export function renderApiReference(spec) {
  const operations = listOperations(spec);
  const groups = groupOperations(asArray(spec.tags), operations);
  const schemas = Object.entries(asObject(asObject(spec.components).schemas));
  const deprecated = operations.filter((entry) => entry.operation.deprecated === true).length;
  const count = operations.length;
  const version = cell(asObject(spec.info).version);
  const lines = [
    '# API reference',
    '',
    `The public \`/v1\` REST API, version ${version}. This page is generated from [\`openapi.json\`](openapi.json) by \`pnpm openapi:generate\`; do not edit it by hand. CI fails when it is stale.`,
    '',
    `It documents ${count} operation${count === 1 ? '' : 's'}${deprecated > 0 ? `, ${deprecated} of them deprecated` : ''}. Read [Conventions](conventions.md) for pagination, idempotency, concurrency and errors, and [Authentication](auth.md) for tokens and scopes.`,
    '',
    'The internal Run Broker API (`/internal/broker`) is not part of this reference.',
    '',
    '## Contents',
    '',
  ];
  for (const group of groups) {
    lines.push(`- ${group.title}`);
    for (const entry of group.entries) {
      const heading = `${entry.method.toUpperCase()} ${entry.route}`;
      lines.push(`  - [${heading}](#${slugify(heading)})`);
    }
  }
  lines.push('');
  for (const group of groups) {
    lines.push(`## ${group.title}`, '');
    if (group.description !== undefined) lines.push(group.description, '');
    for (const entry of group.entries) lines.push(...operationSection(spec, entry));
  }
  if (schemas.length > 0) {
    lines.push('## Schemas', '');
    for (const [name, schema] of schemas) lines.push(...schemaSection(name, asObject(schema)));
  }
  return `${lines
    .join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .trimEnd()}\n`;
}

/**
 * Renders the committed spec under `root` and formats the result with the repository's Prettier config, so
 * the committed page is the formatted output and the staleness check compares like with like.
 * @param {string} root repository root
 * @returns {Promise<string>} the Markdown the committed reference must equal
 */
export async function renderFromRoot(root) {
  const spec = parseSpec(readFileSync(path.join(root, SPEC_FILE), 'utf8'));
  const target = path.join(root, REFERENCE_FILE);
  const options = (await prettier.resolveConfig(target)) ?? {};
  return prettier.format(renderApiReference(spec), { ...options, filepath: target });
}

/**
 * Writes the reference (`check` false), or reports whether the committed one is stale (`check` true).
 * A missing committed page is stale.
 * @param {{ root: string, check: boolean }} options
 * @returns {Promise<{ stale: boolean }>}
 */
export async function syncReference({ root, check }) {
  const markdown = await renderFromRoot(root);
  const target = path.join(root, REFERENCE_FILE);
  if (!check) {
    writeFileSync(target, markdown);
    return { stale: false };
  }
  /** @type {string} */
  let committed;
  try {
    committed = readFileSync(target, 'utf8');
  } catch {
    return { stale: true };
  }
  return { stale: committed !== markdown };
}

/**
 * @param {string[]} argv
 * @returns {Promise<number>} the process exit code
 */
export async function main(argv) {
  const rootIndex = argv.indexOf('--root');
  const root = rootIndex >= 0 ? argv[rootIndex + 1] : process.cwd();
  if (rootIndex >= 0 && (root === undefined || root.startsWith('--'))) {
    process.stderr.write('usage: render-api-reference.mjs [--check] [--root <dir>]\n');
    return 2;
  }
  try {
    const { stale } = await syncReference({
      root: /** @type {string} */ (root),
      check: argv.includes('--check'),
    });
    if (stale) {
      process.stderr.write(
        `${REFERENCE_FILE} is out of date. Run \`pnpm openapi:generate\` and commit it.\n`,
      );
      return 1;
    }
    return 0;
  } catch (error) {
    process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
    return 1;
  }
}

if (
  process.argv[1] !== undefined &&
  fileURLToPath(import.meta.url) === path.resolve(process.argv[1])
) {
  main(process.argv.slice(2)).then(
    (code) => {
      process.exitCode = code;
    },
    (/** @type {unknown} */ error) => {
      process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
      process.exitCode = 1;
    },
  );
}
